contracts/AddressScanner.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract AddressScanner {
    function computeCreateAddress(address sender, uint256 nonce) public pure returns (address) {
        bytes memory encoded;
        if (nonce == 0) {
            encoded = abi.encodePacked(bytes1(0xd6), bytes1(0x94), sender, bytes1(0x80));
        } else if (nonce < 0x80) {
            encoded = abi.encodePacked(bytes1(0xd6), bytes1(0x94), sender, bytes1(uint8(nonce)));
        } else if (nonce < 0x100) {
            encoded = abi.encodePacked(bytes1(0xd7), bytes1(0x94), sender, bytes1(0x81), bytes1(uint8(nonce)));
        } else if (nonce < 0x10000) {
            encoded = abi.encodePacked(bytes1(0xd8), bytes1(0x94), sender, bytes1(0x82), bytes2(uint16(nonce)));
        } else if (nonce < 0x1000000) {
            encoded = abi.encodePacked(bytes1(0xd9), bytes1(0x94), sender, bytes1(0x83), bytes3(uint24(nonce)));
        } else if (nonce < 0x100000000) {
            encoded = abi.encodePacked(bytes1(0xda), bytes1(0x94), sender, bytes1(0x84), bytes4(uint32(nonce)));
        } else {
            revert("Nonce too large");
        }
        bytes32 hash = keccak256(encoded);
        return address(uint160(uint256(hash)));
    }

    function hasCode(address addr) public view returns (bool, uint256) {
        uint256 size;
        assembly { size := extcodesize(addr) }
        return (size > 0, size);
    }

    function scanAddresses(address deployer, uint256 count) public view returns (
        address[] memory addresses,
        bool[] memory hasCodes,
        uint256[] memory codeSizes
    ) {
        addresses = new address[](count);
        hasCodes = new bool[](count);
        codeSizes = new uint256[](count);
        for (uint256 i = 0; i < count; i++) {
            addresses[i] = computeCreateAddress(deployer, i);
            (bool has, uint256 size) = hasCode(addresses[i]);
            hasCodes[i] = has;
            codeSizes[i] = size;
        }
    }
}

contracts/CasinoCore.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Math} from "@openzeppelin/contracts/utils/math/Math.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

interface ILiquidityRouter {
    function depositLiquidity(uint256 amount) external;
}

interface ICasinoReserve {
    function deposit(uint256 amount) external;
    function payWinner(address to, uint256 amount) external;
    function reserveHealth() external view returns (uint256);
}

interface IRNGEngine {
    function requestRandomWords() external returns (uint256 requestId);
}

contract CasinoCore is ReentrancyGuard {
    using SafeERC20 for IERC20;

    error NotGovernance();
    error NotRng();
    error BetBelowMinimum();
    error BetAboveMaximum();
    error BetNotFound();
    error BetNotClaimable();
    error NotBetPlayer();
    error TransferFailed();
    error InvalidPercentageSum();
    error ZeroAddress();
    error CasinoPaused();
    error ExceedsMaxPayout();
    error MaxPayoutExceedsReserve();
    error TooManyBetsInBlock();
    error InvalidBetLimit();
    error InvalidTarget();
    error ZeroAmount();
    error AmountTooLarge();
    error ActiveBetsPreventModuleChange();
    error DuplicateRandomnessRequest();

    enum BetStatus {
        None,
        Pending,
        Settled,
        Claimed
    }

    struct Bet {
        address player;
        uint256 amount;
        uint256 payout;
        uint256 reservedPayout;
        uint8 target;
        uint8 roll;
        BetStatus status;
        bool win;
    }

    event BetPlaced(
        uint256 indexed betId,
        address indexed player,
        uint256 amount,
        uint8 target
    );
    event BetRequested(
        uint256 indexed betId,
        uint256 indexed requestId,
        address indexed player,
        uint256 reservedPayout
    );
    event BetResolved(uint256 indexed betId, uint8 roll, bool win, uint256 payout);
    event PayoutClaimed(uint256 indexed betId, address indexed player, uint256 payout);
    event PercentagesUpdated(uint256 payout, uint256 liquidity, uint256 reserve, uint256 dev);
    event BetLimitsUpdated(uint256 minBet, uint256 maxBet);
    event MaxPayoutUpdated(uint256 oldMaxPayout, uint256 newMaxPayout);
    event PauseChanged(bool paused);
    event MaxBetsPerBlockUpdated(uint256 oldLimit, uint256 newLimit);

    IERC20 public mtx;
    ILiquidityRouter public liquidity;
    ICasinoReserve public reserve;
    IRNGEngine public rng;

    uint256 public payoutPercent = 88;
    uint256 public liquidityPercent = 6;
    uint256 public reservePercent = 4;
    uint256 public devPercent = 2;
    uint256 public maxPayoutPerBet;
    uint256 public minBet;
    uint256 public maxBet;
    address public dev;
    address public governance;

    bool public paused;
    uint256 public maxBetsPerBlock = 3;
    uint256 public totalBets;
    uint256 public totalWagered;
    uint256 public totalPayout;
    uint256 public lockedPayouts;
    uint256 public activeRandomnessRequests;
    int256 public houseProfit;
    uint256 public nextBetId;

    uint8 public constant MIN_TARGET = 2;
    uint8 public constant MAX_TARGET = 98;
    uint256 public constant HOUSE_RETURN_BPS = 9800;
    uint256 private constant BPS_DENOMINATOR = 10000;

    mapping(address => mapping(uint256 => uint256)) private _betsInBlock;
    mapping(uint256 => uint256) public requestToBetId;
    mapping(uint256 => Bet) private _bets;

    constructor(
        address _mtx,
        address _liquidity,
        address _reserve,
        address _rng,
        uint256 _minBet,
        uint256 _maxBet,
        uint256 _maxPayoutPerBet,
        address _dev,
        address _governance
    ) {
        if (
            _mtx == address(0) ||
            _liquidity == address(0) ||
            _reserve == address(0) ||
            _rng == address(0) ||
            _dev == address(0) ||
            _governance == address(0)
        ) revert ZeroAddress();
        if (_minBet == 0 || _maxBet == 0 || _minBet > _maxBet) revert InvalidBetLimit();
        if (_maxPayoutPerBet == 0) revert ZeroAmount();

        mtx = IERC20(_mtx);
        liquidity = ILiquidityRouter(_liquidity);
        reserve = ICasinoReserve(_reserve);
        rng = IRNGEngine(_rng);
        minBet = _minBet;
        maxBet = _maxBet;
        maxPayoutPerBet = _maxPayoutPerBet;
        dev = _dev;
        governance = _governance;
    }

    modifier onlyGovernance() {
        if (msg.sender != governance) revert NotGovernance();
        _;
    }

    modifier notPaused() {
        if (paused) revert CasinoPaused();
        _;
    }

    function placeDiceBet(uint256 amount, uint8 target)
        external
        notPaused
        nonReentrant
        returns (uint256 betId)
    {
        if (amount < minBet) revert BetBelowMinimum();
        if (amount > maxBet) revert BetAboveMaximum();
        if (target < MIN_TARGET || target > MAX_TARGET) revert InvalidTarget();

        uint256 blockBets = _betsInBlock[msg.sender][block.number];
        if (blockBets >= maxBetsPerBlock) revert TooManyBetsInBlock();
        _betsInBlock[msg.sender][block.number] = blockBets + 1;

        uint256 potentialPayout = _calculateDicePayout(amount, target);
        if (potentialPayout > maxPayoutPerBet) revert ExceedsMaxPayout();
        if (
            amount > uint256(type(int256).max) ||
            potentialPayout > uint256(type(int256).max)
        ) revert AmountTooLarge();

        uint256 reserveBal = reserve.reserveHealth();
        if (lockedPayouts > reserveBal || potentialPayout > reserveBal - lockedPayouts) {
            revert MaxPayoutExceedsReserve();
        }

        mtx.safeTransferFrom(msg.sender, address(this), amount);

        uint256 liquidityAmount = Math.mulDiv(amount, liquidityPercent, 100);
        uint256 reserveAmount =
            Math.mulDiv(amount, payoutPercent, 100) +
            Math.mulDiv(amount, reservePercent, 100);
        uint256 devAmount = Math.mulDiv(amount, devPercent, 100);

        if (liquidityAmount > 0) {
            mtx.safeTransfer(address(liquidity), liquidityAmount);
            liquidity.depositLiquidity(liquidityAmount);
        }
        if (reserveAmount > 0) {
            mtx.safeTransfer(address(reserve), reserveAmount);
            reserve.deposit(reserveAmount);
        }
        if (devAmount > 0) mtx.safeTransfer(dev, devAmount);

        betId = ++nextBetId;
        _bets[betId] = Bet({
            player: msg.sender,
            amount: amount,
            payout: 0,
            reservedPayout: potentialPayout,
            target: target,
            roll: 0,
            status: BetStatus.Pending,
            win: false
        });
        lockedPayouts += potentialPayout;
        activeRandomnessRequests++;

        uint256 requestId = rng.requestRandomWords();
        if (requestToBetId[requestId] != 0) revert DuplicateRandomnessRequest();
        requestToBetId[requestId] = betId;

        totalBets++;
        totalWagered += amount;
        emit BetPlaced(betId, msg.sender, amount, target);
        emit BetRequested(betId, requestId, msg.sender, potentialPayout);
    }

    function fulfillRandomness(uint256 requestId, uint256 randomWord) external {
        if (msg.sender != address(rng)) revert NotRng();

        uint256 betId = requestToBetId[requestId];
        if (betId == 0) return;

        Bet storage bet = _bets[betId];
        if (bet.status != BetStatus.Pending) return;

        delete requestToBetId[requestId];
        activeRandomnessRequests--;

        uint8 roll = uint8(randomWord % 100) + 1;
        bool win = roll < bet.target;
        uint256 payout = win ? _calculateDicePayout(bet.amount, bet.target) : 0;

        lockedPayouts -= bet.reservedPayout - payout;
        bet.reservedPayout = payout;
        bet.payout = payout;
        bet.roll = roll;
        bet.win = win;
        bet.status = BetStatus.Settled;
        totalPayout += payout;
        houseProfit += int256(bet.amount) - int256(payout);

        emit BetResolved(betId, roll, win, payout);
    }

    function claimPayout(uint256 betId) external nonReentrant {
        Bet storage bet = _bets[betId];
        if (bet.status == BetStatus.None) revert BetNotFound();
        if (bet.player != msg.sender) revert NotBetPlayer();
        if (bet.status != BetStatus.Settled || !bet.win) revert BetNotClaimable();

        bet.status = BetStatus.Claimed;
        lockedPayouts -= bet.payout;
        reserve.payWinner(msg.sender, bet.payout);
        emit PayoutClaimed(betId, msg.sender, bet.payout);
    }

    function getBet(uint256 betId)
        external
        view
        returns (
            address player,
            uint256 amount,
            uint8 target,
            uint8 roll,
            BetStatus status,
            bool win,
            uint256 payout
        )
    {
        Bet storage bet = _bets[betId];
        if (bet.status == BetStatus.None) revert BetNotFound();
        return (bet.player, bet.amount, bet.target, bet.roll, bet.status, bet.win, bet.payout);
    }

    function previewPayout(uint256 amount, uint8 target) external pure returns (uint256) {
        if (target < MIN_TARGET || target > MAX_TARGET) revert InvalidTarget();
        return _calculateDicePayout(amount, target);
    }

    function reserveBalance() external view returns (uint256) {
        return reserve.reserveHealth();
    }

    function houseEdgeBps() external pure returns (uint256) {
        return BPS_DENOMINATOR - HOUSE_RETURN_BPS;
    }

    function updatePercentages(
        uint256 payout,
        uint256 liquidity_,
        uint256 reserve_,
        uint256 dev_
    ) external onlyGovernance {
        if (
            payout > 100 ||
            liquidity_ > 100 ||
            reserve_ > 100 ||
            dev_ > 100 ||
            payout + liquidity_ + reserve_ + dev_ != 100
        ) revert InvalidPercentageSum();
        payoutPercent = payout;
        liquidityPercent = liquidity_;
        reservePercent = reserve_;
        devPercent = dev_;
        emit PercentagesUpdated(payout, liquidity_, reserve_, dev_);
    }

    function setBetLimits(uint256 _minBet, uint256 _maxBet) external onlyGovernance {
        if (_minBet == 0 || _maxBet == 0 || _minBet > _maxBet) revert InvalidBetLimit();
        minBet = _minBet;
        maxBet = _maxBet;
        emit BetLimitsUpdated(_minBet, _maxBet);
    }

    function setMaxPayoutPerBet(uint256 _maxPayout) external onlyGovernance {
        if (_maxPayout == 0) revert ZeroAmount();
        emit MaxPayoutUpdated(maxPayoutPerBet, _maxPayout);
        maxPayoutPerBet = _maxPayout;
    }

    function setMaxBetsPerBlock(uint256 _maxBets) external onlyGovernance {
        emit MaxBetsPerBlockUpdated(maxBetsPerBlock, _maxBets);
        maxBetsPerBlock = _maxBets;
    }

    function setPaused(bool _paused) external onlyGovernance {
        paused = _paused;
        emit PauseChanged(_paused);
    }

    function setReserve(address _reserve) external onlyGovernance {
        if (_reserve == address(0)) revert ZeroAddress();
        if (activeRandomnessRequests != 0 || lockedPayouts != 0) {
            revert ActiveBetsPreventModuleChange();
        }
        reserve = ICasinoReserve(_reserve);
    }

    function setRng(address _rng) external onlyGovernance {
        if (_rng == address(0)) revert ZeroAddress();
        if (activeRandomnessRequests != 0) revert ActiveBetsPreventModuleChange();
        rng = IRNGEngine(_rng);
    }

    function setLiquidity(address _liquidity) external onlyGovernance {
        if (_liquidity == address(0)) revert ZeroAddress();
        liquidity = ILiquidityRouter(_liquidity);
    }

    function setDev(address _dev) external onlyGovernance {
        if (_dev == address(0)) revert ZeroAddress();
        dev = _dev;
    }

    function setGovernance(address _governance) external onlyGovernance {
        if (_governance == address(0)) revert ZeroAddress();
        governance = _governance;
    }

    function setMtx(address _mtx) external onlyGovernance {
        if (_mtx == address(0)) revert ZeroAddress();
        if (activeRandomnessRequests != 0 || lockedPayouts != 0) {
            revert ActiveBetsPreventModuleChange();
        }
        mtx = IERC20(_mtx);
    }

    function seedReserve() external onlyGovernance {
        uint256 actualBalance = mtx.balanceOf(address(reserve));
        uint256 currentBalance = reserve.reserveHealth();
        if (actualBalance <= currentBalance) revert ZeroAmount();
        reserve.deposit(actualBalance - currentBalance);
    }

    function emergencyWithdraw(address to, uint256 amount) external onlyGovernance {
        if (to == address(0)) revert ZeroAddress();
        mtx.safeTransfer(to, amount);
    }

    function _calculateDicePayout(uint256 amount, uint8 target) private pure returns (uint256) {
        return Math.mulDiv(amount, HOUSE_RETURN_BPS, 100 * (uint256(target) - 1));
    }
}

contracts/CasinoReserve.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";

/**
 * @title CasinoReserve
 * @author Matrix-Hub Team
 * @notice Holds MTX reserves for casino payouts on Polygon
 * @dev Manages reserve balance and payout distribution
 */
contract CasinoReserve {
    using SafeERC20 for IERC20;

    // Custom errors for gas efficiency
    error NotAuthorized();
    error InsufficientReserve();
    error MTXTransferFailed();
    error ZeroAddress();
    error ZeroAmount();
    error ExceedsReserveCap();

    /// @notice Emitted when the owner provides initial reserve funding.
    /// @param amount Amount of MTX added to the reserve.
    event ReserveFunded(uint256 amount);

    /// @notice MTX token contract
    IERC20 public mtx;

    /// @notice Current reserve balance
    uint256 public reserveBalance;

    /// @notice Maximum reserve capacity
    uint256 public reserveCap;

    /// @notice CasinoCore contract address
    address public casinoCore;

    /// @notice Owner address for administrative functions
    address public owner;

    /**
     * @notice Modifier to restrict access to CasinoCore only
     */
    modifier onlyCasinoCore() {
        if (msg.sender != casinoCore) revert NotAuthorized();
        _;
    }

    /**
     * @notice Constructor initializes reserve with MTX token address
     * @dev Sets up reserve parameters and CasinoCore integration
     * @param _mtx Address of deployed MatrixHubCoin (MTX) ERC-20 contract on Polygon
     * @param _reserveCap Maximum reserve capacity in MTX
     * @param _casinoCore Address of CasinoCore contract
     */
    constructor(address _mtx, uint256 _reserveCap, address _casinoCore) {
        if (_mtx == address(0)) revert ZeroAddress();
        if (_reserveCap == 0) revert ZeroAmount();
        mtx = IERC20(_mtx); // MTX Token address on Polygon - set from deployed MatrixHubCoin
        reserveCap = _reserveCap;
        casinoCore = _casinoCore; // can be address(0) — set later via setCasinoCore
        owner = msg.sender;
    }

    /**
     * @notice Update the CasinoCore address (owner only)
     * @dev Used to resolve circular deployment dependency
     * @param _casinoCore New CasinoCore contract address
     */
    function setCasinoCore(address _casinoCore) external {
        if (msg.sender != owner) revert NotAuthorized();
        if (_casinoCore == address(0)) revert ZeroAddress();
        casinoCore = _casinoCore;
    }

    /**
     * @notice Deposit MTX coins to reserve
     * @dev Only callable by CasinoCore, enforces reserve cap
     * @param amount Amount of MTX to deposit
     */
    function deposit(uint256 amount) external onlyCasinoCore {
        if (amount == 0) revert ZeroAmount();
        _recordDeposit(amount);
    }

    /**
     * @notice Fund the reserve before the casino begins accepting bets.
     * @dev Pulls MTX from the owner and updates the tracked reserve balance.
     * @param amount Amount of MTX to add to the reserve.
     */
    function fund(uint256 amount) external {
        if (msg.sender != owner) revert NotAuthorized();
        if (amount == 0) revert ZeroAmount();

        _recordDeposit(amount);
        mtx.safeTransferFrom(msg.sender, address(this), amount);
        emit ReserveFunded(amount);
    }

    /**
     * @notice Pay winner in MTX coins
     * @dev Only callable by CasinoCore
     * @param player Address of the player to pay
     * @param amount Amount of MTX to pay
     */
    function payWinner(address player, uint256 amount) external onlyCasinoCore {
        if (player == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (reserveBalance < amount) revert InsufficientReserve();
        reserveBalance -= amount;
        if (!mtx.transfer(player, amount)) revert MTXTransferFailed();
    }

    /**
     * @notice Check reserve health
     * @dev Returns current reserve balance
     * @return Current reserve balance
     */
    function reserveHealth() external view returns (uint256) {
        return reserveBalance;
    }

    function _recordDeposit(uint256 amount) private {
        if (reserveBalance + amount > reserveCap) revert ExceedsReserveCap();
        reserveBalance += amount;
    }
}

contracts/KeccakHasher.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @title KeccakHasher
/// @notice A minimal contract that computes the keccak256 hash of arbitrary calldata.
contract KeccakHasher {
    /// @notice Returns the keccak256 hash of the calldata (msg.data minus the selector).
    /// @dev The fallback function receives all raw calldata after the first 4 bytes
    ///      (function selector) — in Remix calling without ABI this passes the full
    ///      calldata. We provide an explicit function to keep it simple and testable.
    function hash(bytes memory data) external pure returns (bytes32) {
        return keccak256(data);
    }

    /// @notice Returns the keccak256 hash of the entire calldata passed to this call.
    function hashCalldata() external pure returns (bytes32) {
        return keccak256(msg.data);
    }
}

contracts/LiquidityRouter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title IQuickSwapV2Router
 * @author Matrix-Hub Team
 * @notice Minimal interface for the QuickSwap V2 router functions used here.
 */
interface IQuickSwapV2Router {
    /// @notice Returns the wrapped native token address used by the router.
    /// @return Wrapped native token address.
    function WETH() external view returns (address);

    /// @notice Adds token/native liquidity and returns the amounts used and LP minted.
    /// @param token ERC-20 token to pair with the native asset.
    /// @param amountTokenDesired Maximum ERC-20 amount to add.
    /// @param amountTokenMin Minimum ERC-20 amount accepted.
    /// @param amountETHMin Minimum native amount accepted.
    /// @param to Recipient of the LP tokens.
    /// @param deadline Latest timestamp at which the operation is valid.
    /// @return amountToken ERC-20 amount added.
    /// @return amountETH Native amount added.
    /// @return liquidity Amount of LP tokens minted.
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256 amountToken, uint256 amountETH, uint256 liquidity);
}

/**
 * @title LiquidityRouter
 * @author Matrix-Hub Team
 * @notice Queues casino MTX fees and adds MTX/WMATIC liquidity through QuickSwap V2.
 * @dev CasinoCore deposits MTX; the owner supplies MATIC separately when providing liquidity.
 */
contract LiquidityRouter is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    error ZeroAddress();
    error ZeroAmount();
    error InvalidContract();
    error NotCasinoCore();
    error NotQuickSwapRouter();
    error InsufficientPendingMTX();
    error Expired();
    error NativeTransferFailed();

    /// @notice MTX token collected from CasinoCore.
    IERC20 public immutable MTX;

    /// @notice QuickSwap V2 Router02 contract.
    IQuickSwapV2Router public immutable QUICKSWAP_V2_ROUTER;

    /// @notice Wrapped native asset used by QuickSwap V2.
    address public immutable WRAPPED_NATIVE;

    /// @notice CasinoCore authorized to deposit MTX fees.
    address public casinoCore;

    /// @notice MTX queued for a future liquidity provision.
    uint256 public pendingMtx;

    /// @notice Emitted when the authorized CasinoCore address changes.
    /// @param previousCore Previous CasinoCore address.
    /// @param newCore New CasinoCore address.
    event CasinoCoreUpdated(address indexed previousCore, address indexed newCore);

    /// @notice Emitted when CasinoCore deposits MTX for liquidity.
    /// @param amount Amount of MTX deposited.
    event LiquidityDeposited(uint256 amount);

    /// @notice Emitted when the owner queues MTX for initial liquidity.
    /// @param amount Amount of MTX queued.
    event InitialLiquidityQueued(uint256 amount);

    /// @notice Emitted when MTX/WMATIC liquidity is provided.
    /// @param provider Owner who called the function and supplied MATIC.
    /// @param lpRecipient Address receiving LP tokens.
    /// @param amountMtx Amount of MTX added.
    /// @param amountMatic Amount of MATIC added.
    /// @param liquidity Amount of LP tokens minted.
    event LiquidityProvided(
        address indexed provider,
        address indexed lpRecipient,
        uint256 amountMtx,
        uint256 amountMatic,
        uint256 liquidity
    );

    /// @notice Emitted when queued MTX is withdrawn by the owner.
    /// @param recipient Address receiving MTX.
    /// @param amount Amount of MTX withdrawn.
    event PendingMtxWithdrawn(address indexed recipient, uint256 amount);

    modifier onlyCasinoCore() {
        if (msg.sender != casinoCore) revert NotCasinoCore();
        _;
    }

    constructor(address _mtx, address _quickSwapRouter) Ownable(msg.sender) {
        if (_mtx == address(0) || _quickSwapRouter == address(0)) revert ZeroAddress();
        if (_mtx.code.length == 0 || _quickSwapRouter.code.length == 0) revert InvalidContract();

        address _wrappedNative = IQuickSwapV2Router(_quickSwapRouter).WETH();
        if (_wrappedNative == address(0)) revert ZeroAddress();
        if (_wrappedNative.code.length == 0) revert InvalidContract();

        MTX = IERC20(_mtx);
        QUICKSWAP_V2_ROUTER = IQuickSwapV2Router(_quickSwapRouter);
        WRAPPED_NATIVE = _wrappedNative;
    }

    /// @notice Accepts native refunds from QuickSwap V2 during liquidity provision.
    receive() external payable {
        if (msg.sender != address(QUICKSWAP_V2_ROUTER)) revert NotQuickSwapRouter();
    }

    /// @notice Set or replace the CasinoCore allowed to deposit MTX fees.
    /// @param _casinoCore New CasinoCore address.
    function setCasinoCore(address _casinoCore) external onlyOwner {
        if (_casinoCore == address(0)) revert ZeroAddress();
        if (_casinoCore.code.length == 0) revert InvalidContract();

        address previousCore = casinoCore;
        casinoCore = _casinoCore;
        emit CasinoCoreUpdated(previousCore, _casinoCore);
    }

    /// @notice Account for MTX already transferred here by CasinoCore.
    /// @param amount Amount of MTX deposited for future liquidity provision.
    function depositLiquidity(uint256 amount) external onlyCasinoCore {
        if (amount == 0) revert ZeroAmount();
        if (MTX.balanceOf(address(this)) < pendingMtx + amount) revert InsufficientPendingMTX();

        pendingMtx += amount;
        emit LiquidityDeposited(amount);
    }

    /// @notice Transfer owner-supplied MTX into the queue to bootstrap the first pool.
    /// @param amount Amount of MTX to queue for liquidity.
    function queueInitialLiquidity(uint256 amount) external onlyOwner {
        if (amount == 0) revert ZeroAmount();

        MTX.safeTransferFrom(msg.sender, address(this), amount);
        pendingMtx += amount;
        emit InitialLiquidityQueued(amount);
    }

    /**
     * @notice Add queued MTX and caller-supplied MATIC to the QuickSwap V2 pool.
     * @dev Any unused MTX stays pending; unused MATIC is returned to the caller.
     * @param amountMtxDesired Maximum pending MTX amount to add.
     * @param amountMtxMin Minimum MTX amount accepted by QuickSwap.
     * @param amountMaticMin Minimum MATIC amount accepted by QuickSwap.
     * @param deadline Latest timestamp at which the operation is valid.
     * @return amountMtx MTX amount actually added.
     * @return amountMatic MATIC amount actually added.
     * @return liquidity Amount of LP tokens minted.
     */
    function provideLiquidity(
        uint256 amountMtxDesired,
        uint256 amountMtxMin,
        uint256 amountMaticMin,
        uint256 deadline
    )
        external
        payable
        onlyOwner
        nonReentrant
        returns (uint256 amountMtx, uint256 amountMatic, uint256 liquidity)
    {
        if (amountMtxDesired == 0 || msg.value == 0) revert ZeroAmount();
        if (deadline < block.timestamp) revert Expired();
        if (amountMtxDesired > pendingMtx) revert InsufficientPendingMTX();

        uint256 balanceBefore = address(this).balance - msg.value;
        pendingMtx -= amountMtxDesired;
        MTX.forceApprove(address(QUICKSWAP_V2_ROUTER), amountMtxDesired);

        (amountMtx, amountMatic, liquidity) = QUICKSWAP_V2_ROUTER.addLiquidityETH{value: msg.value}(
            address(MTX),
            amountMtxDesired,
            amountMtxMin,
            amountMaticMin,
            msg.sender,
            deadline
        );

        MTX.forceApprove(address(QUICKSWAP_V2_ROUTER), 0);
        pendingMtx += amountMtxDesired - amountMtx;

        uint256 unusedMatic = address(this).balance - balanceBefore;
        if (unusedMatic > 0) {
            (bool refunded,) = payable(msg.sender).call{value: unusedMatic}("");
            if (!refunded) revert NativeTransferFailed();
        }

        emit LiquidityProvided(msg.sender, msg.sender, amountMtx, amountMatic, liquidity);
    }

    /// @notice Recover queued MTX without adding liquidity.
    /// @param recipient Address receiving the withdrawn MTX.
    /// @param amount Amount of pending MTX to withdraw.
    function withdrawPendingMtx(address recipient, uint256 amount) external onlyOwner {
        if (recipient == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (amount > pendingMtx) revert InsufficientPendingMTX();

        pendingMtx -= amount;
        MTX.safeTransfer(recipient, amount);
        emit PendingMtxWithdrawn(recipient, amount);
    }
}

